async function main(): Promise<void> {
  const src: any = new Function('return [Promise.resolve(1), 2, Promise.resolve(3)]')();
  for await (const v of src) { console.log('v', v); }
  const gen: any = new Function('return (async function* () { yield 10; yield 20; })()')();
  for await (const g of gen) { console.log('g', g); }
  const plain: any = [7, 8];
  for await (const p of plain) { console.log('p', p); }
}
